+function waitForExit(child: ChildProcess, timeout: number): Promise<void> {
+  return new Promise(resolve => {
+    let done = false;
+    const finish = () => {
+      if (done) {
+        return;
+      }
+      done = true;
+      clearTimeout(timer);
+      resolve();
+    };
+    const timer = setTimeout(() => {
+      if (child.exitCode == null) {
+        child.kill('SIGKILL');
+      }
+      finish();
+    }, timeout);
+
+    if (child.exitCode != null) {
+      finish();
+      return;
+    }
+    child.once('exit', finish);
+    child.once('error', finish);
+  });
+}
